                                    .WithTags(""ToDo"")
                                    .WithDescriptionFromFile(""V1.GetAll.Documentation.GetAllTodoDescription.txt"")
                                    .WithDescription(""Legacy version"")
                                    .WithOpenApi()
                                    .MapToApiVersion(1)
                                    .MapToApiVersion(new ApiVersion(1.0));
        }}
    }}

}}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
